// Robust: handle two common Google Sheets outputs:
// 1) multiple items (one per row) -> items = [ { json: { id, order_id, ... } }, ... ]
// 2) single item whose json is an array -> items = [ { json: [ {...}, {...} ] } ]

function normalizeRow(r) {
  return {
    id: r.id,
    order_id: r.order_id,
    email: (r.email || '').toLowerCase(),
    total: Number(r.total || 0),
    created_at: r.created_at,
    utm_source: (r.utm_source || '').toLowerCase() || null,
    utm_campaign: r.utm_campaign || 'unknown'
  };
}

// Case A: items is an array of row-items
if (Array.isArray(items) && items.length > 0 && items[0] && typeof items[0].json === 'object' && !Array.isArray(items[0].json)) {
  return items.map(i => ({ json: normalizeRow(i.json) }));
}

// Case B: single item whose .json is an array of rows (some Sheets nodes behave like this)
if (items.length === 1 && Array.isArray(items[0].json)) {
  const rows = items[0].json;
  return rows.map(r => ({ json: normalizeRow(r) }));
}

// Fallback: if nothing matched, return empty
return [];

// Combine Sheets (split) - works with Merge mode = Append
// Input: items = array containing all rows from Ads, Leads, Orders (mixed)
// Output: single item with { ads: [...], leads: [...], orders: [...] }

// helpers
const normEmail = e => (e === null || typeof e === 'undefined') ? null : String(e).trim().toLowerCase();
const toNum = x => { const n = Number(x); return Number.isFinite(n) ? n : 0; };

// Prepare arrays and maps for dedupe
const adsMap = new Map();    // key: platform|campaign|date
const leadsMap = new Map();  // key: email
const ordersMap = new Map(); // key: order_id

// Iterate over every merged item (one per original row)
for (const it of items) {
  const r = it.json || {};

  // Detect ad row: existence of platform or clicks/spend/impressions
  const hasAdFields = Boolean(r.platform || r.clicks || r.spend || r.impressions || r.campaign || r.date);
  // Detect order row: presence of order_id
  const hasOrder = Boolean(r.order_id || r.orderId || r.order || r.order_id === 0);
  // Detect lead row: presence of email and lead indicators
  const hasLead = Boolean(r.email && (r.lead_status || r.name || r.utm_source || r.utm_campaign || !hasAdFields && !hasOrder));

  // --- Ads ---
  if (hasAdFields) {
    const platform = String(r.platform || 'unknown');
    const campaign = String(r.campaign || 'unknown');
    const date = String(r.date || (r.created_at ? String(r.created_at).split('T')[0] : 'unknown'));
    const key = `${platform}|${campaign}|${date}`;
    if (!adsMap.has(key)) {
      adsMap.set(key, {
        platform,
        campaign,
        date,
        clicks: toNum(r.clicks || r.click || 0),
        spend: toNum(r.spend || 0),
        impressions: toNum(r.impressions || 0)
      });
    } else {
      const ex = adsMap.get(key);
      ex.clicks += toNum(r.clicks || r.click || 0);
      ex.spend += toNum(r.spend || 0);
      ex.impressions += toNum(r.impressions || 0);
      adsMap.set(key, ex);
    }
  }

  // --- Orders ---
  if (hasOrder) {
    const oid = String(r.order_id || r.orderId || r.order || '');
    if (oid) {
      if (!ordersMap.has(oid)) {
        ordersMap.set(oid, {
          order_id: oid,
          email: r.email ? normEmail(r.email) : null,
          total: toNum(r.total || r.total_price || 0),
          created_at: r.created_at || null,
          utm_source: (r.utm_source || null),
          utm_campaign: (r.utm_campaign || null)
        });
      } else {
        const ex = ordersMap.get(oid);
        ex.email = ex.email || (r.email ? normEmail(r.email) : ex.email);
        ex.total = ex.total || toNum(r.total || r.total_price || 0);
        ex.utm_source = ex.utm_source || (r.utm_source || null);
        ordersMap.set(oid, ex);
      }
    }
  }

  // --- Leads ---
  if (hasLead) {
    const email = r.email ? normEmail(r.email) : null;
    if (email) {
      if (!leadsMap.has(email)) {
        leadsMap.set(email, {
          email,
          name: r.name || null,
          utm_source: r.utm_source || null,
          utm_campaign: r.utm_campaign || null,
          lead_status: r.lead_status || null,
          created_at: r.created_at || null
        });
      } else {
        const ex = leadsMap.get(email);
        ex.name = ex.name || r.name || ex.name;
        ex.utm_source = ex.utm_source || r.utm_source || ex.utm_source;
        ex.utm_campaign = ex.utm_campaign || r.utm_campaign || ex.utm_campaign;
        ex.lead_status = ex.lead_status || r.lead_status || ex.lead_status;
        leadsMap.set(email, ex);
      }
    }
  }
}

// Convert maps to arrays
const adsArr = Array.from(adsMap.values());
const leadsArr = Array.from(leadsMap.values());
const ordersArr = Array.from(ordersMap.values());

// Return single combined item
return [
  {
    json: {
      ads: adsArr,
      leads: leadsArr,
      orders: ordersArr
    }
  }
];

// Attribution & Aggregation - complete
// Expects items[0].json = { ads: [...], leads: [...], orders: [...] }

// Helpers
const norm = s => (s === null || typeof s === 'undefined') ? null : String(s).trim().toLowerCase();
const toNum = x => { const n = Number(x); return Number.isFinite(n) ? n : 0; };
const datePart = ts => (ts ? String(ts).split('T')[0] : 'unknown');

// Input
const payload = items[0].json || {};
const adsArr = Array.isArray(payload.ads) ? payload.ads : [];
const leadsArr = Array.isArray(payload.leads) ? payload.leads : [];
const ordersArr = Array.isArray(payload.orders) ? payload.orders : [];

// Build lead lookup by email
const leadsByEmail = new Map();
leadsArr.forEach(l => {
  if (l.email) leadsByEmail.set(norm(l.email), {
    email: norm(l.email),
    utm_source: norm(l.utm_source) || null,
    utm_campaign: l.utm_campaign || null,
    created_at: l.created_at || null
  });
});

// Build ad buckets (platform|campaign|date)
const adBuckets = [];
adsArr.forEach(a => {
  adBuckets.push({
    platform: norm(a.platform) || 'unknown',
    campaign: a.campaign || 'unknown',
    date: a.date || (a.created_at ? datePart(a.created_at) : 'unknown'),
    clicks: toNum(a.clicks || 0),
    spend: toNum(a.spend || 0),
    impressions: toNum(a.impressions || 0)
  });
});

// Utility to find nearest ad bucket by date (within windowDays)
function findNearestAdBucket(orderDateStr, windowDays = 7) {
  if (!orderDateStr) return null;
  try {
    const orderDate = new Date(orderDateStr.split('T')[0]);
    let best = null;
    let bestDiff = Infinity;
    for (const b of adBuckets) {
      if (!b.date || b.date === 'unknown') continue;
      const adDate = new Date(b.date);
      const diffDays = Math.abs((orderDate - adDate) / (1000*60*60*24));
      if (diffDays <= windowDays && diffDays < bestDiff) {
        bestDiff = diffDays;
        best = b;
      }
    }
    return best;
  } catch (e) {
    return null;
  }
}

// Attribution: per order
const attributionLog = [];
const attributedOrders = ordersArr.map(o => {
  const order = {
    order_id: String(o.order_id || o.id || 'unknown'),
    email: o.email ? norm(o.email) : null,
    total: toNum(o.total || o.total_price || 0),
    created_at: o.created_at || null,
    utm_source: norm(o.utm_source) || null,
    utm_campaign: o.utm_campaign || null
  };

  let derived_source = null;
  let method = null;
  let confidence = 0.0;

  // 1) Email match to leads
  if (order.email && leadsByEmail.has(order.email)) {
    const lead = leadsByEmail.get(order.email);
    derived_source = lead.utm_source || order.utm_source || null;
    method = 'email_match';
    confidence = 0.95;
  }
  // 2) order.utm_source present
  else if (order.utm_source) {
    derived_source = order.utm_source;
    method = 'order_utm';
    confidence = 0.8;
  }
  // 3) fallback: nearest ad bucket by date proximity
  else if (order.created_at) {
    const near = findNearestAdBucket(order.created_at, 7); // 7-day window
    if (near) {
      derived_source = near.platform || null;
      method = 'date_proximity_ad';
      confidence = 0.4;
    } else {
      method = 'unattributed';
      confidence = 0.0;
    }
  } else {
    method = 'unattributed';
    confidence = 0.0;
  }

  attributionLog.push({
    order_id: order.order_id,
    email: order.email,
    created_at: order.created_at,
    derived_source,
    method,
    confidence,
    utm_campaign: order.utm_campaign || null,
    total: order.total
  });

  return {
    order_id: order.order_id,
    email: order.email,
    total: order.total,
    created_at: order.created_at,
    utm_campaign: order.utm_campaign,
    derived_source,
    method,
    confidence
  };
});

// Build metrics buckets keyed by channel|campaign|date
const metricsMap = new Map();

// Seed metrics from adBuckets
adBuckets.forEach(a => {
  const key = `${a.platform}|${a.campaign}|${a.date}`;
  metricsMap.set(key, {
    channel: a.platform,
    campaign: a.campaign,
    date: a.date,
    clicks: a.clicks,
    spend: a.spend,
    impressions: a.impressions,
    orders: 0,
    revenue: 0
  });
});

// Add attributed orders into buckets
attributedOrders.forEach(o => {
  const channel = o.derived_source || 'unattributed';
  const campaign = o.utm_campaign || 'unknown';
  const date = o.created_at ? String(o.created_at).split('T')[0] : 'unknown';
  const key = `${channel}|${campaign}|${date}`;
  if (!metricsMap.has(key)) {
    metricsMap.set(key, {
      channel,
      campaign,
      date,
      clicks: 0,
      spend: 0,
      impressions: 0,
      orders: 0,
      revenue: 0
    });
  }
  const m = metricsMap.get(key);
  m.orders += 1;
  m.revenue += toNum(o.total || 0);
  metricsMap.set(key, m);
});

// Compute metric fields and prepare metric items
const metrics = [];
for (const [k, m] of metricsMap.entries()) {
  const CPC = m.clicks ? (m.spend / m.clicks) : null;
  const CPA = m.orders ? (m.spend / m.orders) : null;
  const ROAS = m.spend ? (m.revenue / m.spend) : null;
  const conversion_rate = m.clicks ? (m.orders / m.clicks) : null;

  metrics.push({
    json: {
      date: m.date,
      channel: m.channel,
      campaign: m.campaign,
      clicks: m.clicks,
      spend: Number(m.spend.toFixed(2)),
      impressions: m.impressions,
      orders: m.orders,
      revenue: Number(m.revenue.toFixed(2)),
      CPC: CPC !== null ? Number(CPC.toFixed(2)) : null,
      CPA: CPA !== null ? Number(CPA.toFixed(2)) : null,
      ROAS: ROAS !== null ? Number(ROAS.toFixed(2)) : null,
      conversion_rate: conversion_rate !== null ? Number((conversion_rate * 100).toFixed(2)) : null
    }
  });
}

// Final log item
const logItem = { json: { attribution_log: attributionLog } };

// Return metrics items then the single log item
return [...metrics, logItem];

// Return only the last item (the attribution_log wrapper)
if (items.length === 0) return [];
return [ items[items.length - 1] ];

// expects single item with json.attribution_log = [...]
const arr = (items[0] && items[0].json && items[0].json.attribution_log) ? items[0].json.attribution_log : [];
return arr.map(r => ({ json: r }));

// --- Start: Helper Functions ---
function normStr(x){
  if (x === null || typeof x === 'undefined') return null;
  return String(x).trim();
}
function normLower(x){
  const s = normStr(x);
  return s ? s.toLowerCase() : null;
}
// Upgraded: Strips currency/symbols. Returns 0 instead of null.
function toNum(x){
  if (x === null || typeof x === 'undefined' || x === '') return 0;
  // Strips all non-numeric characters except for decimal and hyphen
  const cleanString = String(x).replace(/[^0-9.-]+/g,"");
  if (cleanString === '') return 0;

  const n = Number(cleanString);
  return Number.isFinite(n) ? n : 0;
}
function getField(row, candidates){
  for (const c of candidates){
    if (c in row && row[c] !== undefined) return row[c];
  }
  const keys = Object.keys(row || {});
  for (const c of candidates){
    const lc = String(c).toLowerCase();
    for (const k of keys){
      if (String(k).toLowerCase() === lc) return row[k];
    }
  }
  const normalizedMap = {};
  for (const k of keys){
    const kk = String(k).replace(/\s+/g,'').toLowerCase();
    normalizedMap[kk] = row[k];
  }
  for (const c of candidates){
    const kk = String(c).replace(/\s+/g,'').toLowerCase();
    if (kk in normalizedMap) return normalizedMap[kk];
  }
  return undefined;
}
// --- End: Helper Functions ---

const processed_rows = [];
let total_spend = 0;
let total_revenue = 0;
let total_clicks = 0;
let total_orders = 0;
let total_impressions = 0;

// 1. FIRST PASS: Loop, normalize, and get totals
for (const it of items) {
  const r = it.json || {};

  // Pull and normalize values
  const date = getField(r, ['date','Date','created_at','createdAt']) ? (normStr(getField(r, ['date','Date','created_at','createdAt'])).split('T')[0]) : null;
  const channel = getField(r, ['channel','Channel','utm_source','source']) ? normLower(getField(r, ['channel','Channel','utm_source','source'])) : 'unattributed';
  const campaign = getField(r, ['campaign','Campaign','utm_campaign']) ? normStr(getField(r, ['campaign','Campaign','utm_campaign'])) : 'unknown';
  const clicks = toNum(getField(r, ['clicks','click','Clicks']));
  const spend = toNum(getField(r, ['spend','spends','Spend','spen','spen ds','spen\n      ds']));
  const impressions = toNum(getField(r, ['impressions','impression','Impressions']));
  const orders = toNum(getField(r, ['orders','order_count','orders_count','Order']));
  const revenue = toNum(getField(r, ['revenue','Revenue','total','total_revenue','total_price']));

  // Calculate row-level metrics (handle division by zero)
  const cpc = clicks > 0 ? Number((spend / clicks).toFixed(2)) : 0;
  const cpa = orders > 0 ? Number((spend / orders).toFixed(2)) : 0;
  const roas = spend > 0 ? Number((revenue / spend).toFixed(2)) : 0;
  const conversion_rate = clicks > 0 ? Number(((orders / clicks) * 100).toFixed(2)) : 0;

  // Add to totals
  total_spend += spend;
  total_revenue += revenue;
  total_clicks += clicks;
  total_orders += orders;
  total_impressions += impressions;

  // Store the processed row
  processed_rows.push({
    date,
    channel,
    campaign,
    clicks,
    spend,
    impressions,
    orders,
    revenue,
    cpc,
    cpa,
    roas,
    conversion_rate
  });
}

// 2. Calculate final aggregate metrics
const agg_average_cpa = total_orders > 0 ? Number((total_spend / total_orders).toFixed(2)) : 0;
const agg_average_roas = total_spend > 0 ? Number((total_revenue / total_spend).toFixed(2)) : 0;
const agg_avg_conversion_rate = total_clicks > 0 ? Number(((total_orders / total_clicks) * 100).toFixed(2)) : 0;
const agg_average_cpc = total_clicks > 0 ? Number((total_spend / total_clicks).toFixed(2)) : 0;


// 3. SECOND PASS: Rebuild the output array
// This flattens ALL data into every row
const final_output = processed_rows.map(row => {
  return {
    json: {
      ...row, // Spread all the row data (date, channel, spend, cpa, roas, etc.)

      // --- Add ALL aggregate values with multiple key names to ensure a match ---

      // For "Total Spend"
      "Total Spend": total_spend, // Matches label
      "total_spend": total_spend, // snake_case
      "totalSpend": total_spend, // camelCase

      // For "Average ROAS"
      "Average ROAS": agg_average_roas, // Matches label
      "average_roas": agg_average_roas, // snake_case
      "averageRoas": agg_average_roas, // camelCase
      "roas_avg": agg_average_roas,

      // For "Average CPA" (This one is WORKING)
      "Average CPA": agg_average_cpa, // Matches label
      "average_cpa": agg_average_cpa, // snake_case
      "averageCpa": agg_average_cpa, // camelCase

      // For "Avg Conversion Rate"
      "Avg Conversion Rate": agg_avg_conversion_rate, // Matches label
      "avg_conversion_rate": agg_avg_conversion_rate, // snake_case
      "avgConversionRate": agg_avg_conversion_rate, // camelCase
      "average_conversion_rate": agg_avg_conversion_rate,
      "averageConversionRate": agg_avg_conversion_rate,

      // Add the other totals just in case
      "total_revenue": total_revenue,
      "totalRevenue": total_revenue,
      "total_orders": total_orders,
      "totalOrders": total_orders,
      "total_clicks": total_clicks,
      "totalClicks": total_clicks
    }
  };
});

return final_output;
